type propertyversionPaginateArgs struct {
	first, last   *int
	after, before *Cursor
	opts          []PropertyVersionPaginateOption
}

func newPropertyVersionPaginateArgs(rv map[string]any) *propertyversionPaginateArgs {
	args := &propertyversionPaginateArgs{}
	if rv == nil {
		return args
	}
	if v := rv[firstField]; v != nil {
		args.first = v.(*int)
	}
	if v := rv[lastField]; v != nil {
		args.last = v.(*int)
	}
	if v := rv[afterField]; v != nil {
		args.after = v.(*Cursor)
	}
	if v := rv[beforeField]; v != nil {
		args.before = v.(*Cursor)
	}
	if v, ok := rv[orderByField]; ok {
		switch v := v.(type) {
		case map[string]any:
			var (
				err1, err2 error
				order      = &PropertyVersionOrder{Field: &PropertyVersionOrderField{}, Direction: entgql.OrderDirectionAsc}
			)
			if d, ok := v[directionField]; ok {
				err1 = order.Direction.UnmarshalGQL(d)
			}
			if f, ok := v[fieldField]; ok {
				err2 = order.Field.UnmarshalGQL(f)
			}
			if err1 == nil && err2 == nil {
				args.opts = append(args.opts, WithPropertyVersionOrder(order))
			}
		case *PropertyVersionOrder:
			if v != nil {
				args.opts = append(args.opts, WithPropertyVersionOrder(v))
			}
		}
	}
	if v, ok := rv[whereField].(*PropertyVersionWhereInput); ok {
		args.opts = append(args.opts, WithPropertyVersionFilter(v.Filter))
	}
	return args
}

// CollectFields tells the query-builder to eagerly load connected nodes by resolver context.
func (_q *SourceSystemQuery) CollectFields(ctx context.Context, satisfies ...string) (*SourceSystemQuery, error) {
	fc := graphql.GetFieldContext(ctx)
	if fc == nil {
		return _q, nil
	}
	if err := _q.collectField(ctx, false, graphql.GetOperationContext(ctx), fc.Field, nil, satisfies...); err != nil {
		return nil, err
	}
	return _q, nil
}

func (_q *SourceSystemQuery) collectField(ctx context.Context, oneNode bool, opCtx *graphql.OperationContext, collected graphql.CollectedField, path []string, satisfies ...string) error {
	path = append([]string(nil), path...)
	var (
		unknownSeen    bool
		fieldSeen      = make(map[string]struct{}, len(sourcesystem.Columns))
		selectedFields = []string{sourcesystem.FieldID}
	)
	for _, field := range graphql.CollectFields(opCtx, collected.Selections, satisfies) {
		switch field.Name {
		case "createdAt":
			if _, ok := fieldSeen[sourcesystem.FieldCreatedAt]; !ok {
				selectedFields = append(selectedFields, sourcesystem.FieldCreatedAt)
				fieldSeen[sourcesystem.FieldCreatedAt] = struct{}{}
			}
		case "modifiedAt":
			if _, ok := fieldSeen[sourcesystem.FieldModifiedAt]; !ok {
				selectedFields = append(selectedFields, sourcesystem.FieldModifiedAt)
				fieldSeen[sourcesystem.FieldModifiedAt] = struct{}{}
			}
		case "sourceSystemName":
			if _, ok := fieldSeen[sourcesystem.FieldSourceSystemName]; !ok {
				selectedFields = append(selectedFields, sourcesystem.FieldSourceSystemName)
				fieldSeen[sourcesystem.FieldSourceSystemName] = struct{}{}
			}
		case "id":
		case "__typename":
		default:
			unknownSeen = true
		}
	}
	if !unknownSeen {
		_q.Select(selectedFields...)
	}
	return nil
}

